create or replace function public.mark_abandoned_checkouts(p_after_minutes integer default 30) returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin update public.checkout_sessions set status='abandoned',abandoned_at=coalesce(abandoned_at,now()),recovery_status=coalesce(nullif(recovery_status,''),'pending') where status in ('started','pending','processing') and updated_at < now()-make_interval(mins=>greatest(1,p_after_minutes)) and completed_at is null; get diagnostics n=row_count; return n; end; $$; revoke execute on function public.mark_abandoned_checkouts(integer) from public,anon,authenticated; grant execute on function public.mark_abandoned_checkouts(integer) to service_role; create index if not exists checkout_sessions_abandonment_idx on public.checkout_sessions (status,updated_at) where status in ('started','pending','processing') and completed_at is null;